def calculate_K(A, B, d):
    K = 0
    for m in A:
        for n in B:
            if abs(m - n) <= d:
                K += 1
    return K

def solve_small(n, m, d):
    A = list(range(n))
    B = list(range(m))
    return calculate_K(A, B, d)

# Let's test some values.
# For A = {0, 1, ..., n-1}, B = {0, 1, ..., m-1}
# The condition is |i - j| <= d
# 0 <= i < n, 0 <= j < m
# -d <= i - j <= d  =>  i - d <= j <= i + d
# So for each i, j is in [max(0, i-d), min(m-1, i+d)]
# The number of such j is min(m-1, i+d) - max(0, i-d) + 1

def count_pairs(n, m, d):
    count = 0
    for i in range(n):
        low = max(0, i - d)
        high = min(m - 1, i + d)
        if low <= high:
            count += (high - low + 1)
    return count

print(f"n=2, m=3, d=1: {count_pairs(2, 3, 1)}")
print(f"n=2000, m=2016, d=1000: {count_pairs(2000, 2016, 1000)}")

