def count_triples(n, m, p, d):
    A = list(range(n))
    B = list(range(m))
    C = list(range(p))
    count = 0
    for a in A:
        for b in B:
            for c in C:
                if abs(a - b) <= d and abs(b - c) <= d and abs(c - a) <= d:
                    count += 1
    return count

def max_triples(n, m, p, d):
    max_k = 0
    for s1 in range(-m - d, n + d):
        for s2 in range(-p - d, m + p + d):
            A = list(range(n))
            B = list(range(s1, s1 + m))
            C = list(range(s2, s2 + p))
            count = 0
            for a in A:
                for b in B:
                    for c in C:
                        if abs(a-b) <= d and abs(b-c) <= d and abs(c-a) <= d:
                            count += 1
            if count > max_k:
                max_k = count
    return max_k

